<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    strictStyleIsolation: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// 开启 Shadow DOM 隔离</span></span>
